54: let seeded = false;
55: 
56: export function seedSources(db: DatabaseSync): number {
57:   const path = join(REPO_CONFIG_PATH, "curiosity-sources.json");
58:   const parsed = JSON.parse(readFileSync(path, "utf-8")) as {
59:     sources: SourceConfig[];
60:   };
61:   for (const source of parsed.sources) upsertSource(db, source);
62:   return parsed.sources.length;
63: }
64: 
65: function dueSources(db: DatabaseSync): SourceRow[] {
66:   const cutoff = Date.now() - env.curiositySourceIntervalHours * 3_600_000;
67:   return listSources(db)
68:     .filter((s) => {
69:       if (!s.last_fetched_at) return true;
70:       return new Date(`${s.last_fetched_at}Z`).getTime() < cutoff;
71:     })
72:     .slice(0, env.curiositySourcesPerTick);
73: }
