75: async function scanSource(
76:   db: DatabaseSync,
77:   source: SourceRow,
78: ): Promise<number> {
79:   try {
80:     const res = await fetch(source.url, {
81:       headers: {
82:         "User-Agent": "composer-assistant/0.2 (personal reader)",
83:         Accept: "application/rss+xml, application/atom+xml, application/xml",
84:       },
85:       signal: AbortSignal.timeout(12_000),
86:     });
87:     if (!res.ok) {
88:       markSourceFetched(db, source.id, `http_${res.status}`);
89:       return 0;
90:     }
91:     const items = parseFeed(await res.text(), env.curiosityItemsPerSource);
92:     let inserted = 0;
93:     for (const item of items) {
94:       const id = insertItem(db, {
95:         sourceId: source.id,
96:         url: item.url,
97:         title: item.title,
98:         excerpt: item.excerpt,
99:         interest: source.interest,
100:         publishedAt: item.publishedAt,
101:         score: scoreItem({
102:           weight: source.weight,
103:           title: item.title,
104:           excerpt: item.excerpt,
105:           publishedAt: item.publishedAt,
106:         }),
107:       });
108:       if (id !== null) inserted++;
109:     }
110:     markSourceFetched(db, source.id, null);
111:     logProvenance(db, "scan", `${source.slug}: ${inserted} new of ${items.length}`);
112:     return inserted;
113:   } catch (err) {
114:     const reason = err instanceof Error ? err.message : "fetch_failed";
115:     markSourceFetched(db, source.id, reason.slice(0, 200));
116:     return 0;
117:   }
118: }
