120: /**
121:  * Scan wide, note a few, read almost none. The feed layer is mute: nothing here
122:  * can reach Doc, only a formed take can, and only through the chat injector.
123:  */
124: export async function runCuriosityTick(
125:   db: DatabaseSync,
126: ): Promise<CuriosityTickResult> {
127:   const result: CuriosityTickResult = {
128:     scanned: 0,
129:     noted: 0,
130:     read: 0,
131:     takes: 0,
132:     watched: 0,
133:   };
134: 
135:   if (!env.curiosityEnabled) return { ...result, skipped: "disabled" };
136:   if (!env.mistralApiKey) return { ...result, skipped: "no_api_key" };
137:   if (isTurnBusy()) return { ...result, skipped: "chat_busy" };
138: 
139:   const gotFlight = await acquireArticleFlight("tick", 0);
140:   if (!gotFlight) return { ...result, skipped: "in_progress" };
141:   clearTickYield();
142: 
143:   try {
144:     if (!seeded) {
145:       seedSources(db);
146:       seeded = true;
147:     }
148: 
149:     for (const source of dueSources(db)) {
150:       if (shouldTickYield() || isTurnBusy()) {
151:         return { ...result, skipped: "preempted" };
152:       }
153:       result.scanned += await scanSource(db, source);
154:     }
155: 
156:     const noteBudget = Math.max(
157:       0,
158:       env.curiosityNotePerDay - countNotedSince(db, 24),
159:     );
160:     for (const item of topScannedItems(db, noteBudget)) {
161:       setItemStatus(db, item.id, "noted");
162:       result.noted++;
163:     }
164: 
165:     let readBudget = Math.max(
166:       0,
167:       env.curiosityReadPerDay - countProvenance(db, "read", 24),
168:     );
169: 
170:     // Read candidates come from the noted pool, not from this tick's scan, or a
171:     // day where the note budget filled early would never be read at all.
172:     for (const item of topNotedItems(db, readBudget * 2)) {
173:       if (readBudget <= 0) break;
174:       if (shouldTickYield() || isTurnBusy()) {
175:         return { ...result, skipped: "preempted" };
176:       }
177:       const article = await fetchArticleText(item.url, 10_000, {
178:         enforceSafeHost: true,
179:       });
180:       const body = article ?? item.excerpt ?? "";
181:       if (body.length < 200) {
182:         setItemStatus(db, item.id, "skipped");
183:         continue;
184:       }
185:       if (article) updateItemExcerpt(db, item.id, article.slice(0, 1200));
186: 
187:       let take: string | null = null;
188:       try {
189:         take = await generateTake({ title: item.title, text: body });
190:       } catch (err) {
191:         console.warn("[curiosity] take failed:", err);
192:       }
193: 
194:       setItemStatus(db, item.id, take ? "read" : "skipped");
195:       if (!take) continue;
196: 
197:       // Only a fetched body licenses provenance "read". Excerpt-only takes
198:       // still form opinions but must not claim a sit-down read.
199:       if (article) {
200:         logProvenance(db, "read", `${item.title} (${item.url})`, item.id);
201:         result.read++;
202:       } else {
203:         logProvenance(
204:           db,
205:           "take",
206:           `excerpt:${item.title} (${item.url})`,
207:           item.id,
208:         );
209:       }
210:       insertTake(db, { itemId: item.id, interest: item.interest, take });
211:       logProvenance(db, "take", take, item.id);
212:       readBudget--;
213:       result.takes++;
214:     }
215: 
216:     if (env.memoryOwnerId) {
217:       if (shouldTickYield() || isTurnBusy()) {
218:         return { ...result, skipped: "preempted" };
219:       }
220:       try {
221:         const facts = listActiveFacts(db, env.memoryOwnerId);
222:         discoverInterestsFromText(
223:           db,
224:           facts.map((f) => `${f.key} ${f.value}`),
225:         );
226:         syncWatchesFromFacts(
227:           db,
228:           env.memoryOwnerId,
229:           facts,
230:           env.curiosityWatchMax,
231:         );
232:         const fired = await runOneDueWatch(db, env.memoryOwnerId);
233:         if (fired) {
234:           result.watched = 1;
235:           result.takes++;
236:         }
237:       } catch (err) {
238:         console.warn("[curiosity] watch pass failed:", err);
239:       }
240:     }
241: 
242:     return result;
243:   } finally {
244:     releaseArticleFlight("tick");
245:   }
246: }
247: 
248: let timer: ReturnType<typeof setInterval> | null = null;
249: 
250: export function startCuriosityLoop(db: DatabaseSync): void {
251:   if (!env.curiosityEnabled) {
252:     console.log("[curiosity] disabled (CURIOSITY_ENABLED=false)");
253:     return;
254:   }
255:   const run = () => {
256:     void runCuriosityTick(db)
257:       .then((r) => {
258:         if (r.skipped) return;
259:         if (r.scanned || r.takes) {
260:           console.log(
261:             `[curiosity] scanned=${r.scanned} noted=${r.noted} read=${r.read}`,
262:           );
263:         }
264:       })
265:       .catch((err) => console.warn("[curiosity] tick error:", err));
266:   };
267:   // Not on boot: a restart should not spend a read budget.
268:   timer = setInterval(run, env.curiosityTickMinutes * 60_000);
269:   console.log(`[curiosity] loop every ${env.curiosityTickMinutes}m`);
270: }
271: 
272: export function stopCuriosityLoop(): void {
273:   if (timer) {
274:     clearInterval(timer);
275:     timer = null;
276:   }
277: }
