13: const ENTITIES: Record<string, string> = {
14:   amp: "&",
15:   lt: "<",
16:   gt: ">",
17:   quot: '"',
18:   apos: "'",
19:   nbsp: " ",
20:   "#39": "'",
21:   "#8217": "'",
22:   "#8216": "'",
23:   "#8220": '"',
24:   "#8221": '"',
25: };
