27: export function decodeEntities(text: string): string {
28:   return text.replace(/&(#?\w+);/g, (whole, name: string) => {
29:     const direct = ENTITIES[name.toLowerCase()];
30:     if (direct) return direct;
31:     if (/^#\d+$/.test(name)) {
32:       return String.fromCodePoint(Number(name.slice(1)));
33:     }
34:     if (/^#x[0-9a-f]+$/i.test(name)) {
35:       return String.fromCodePoint(Number.parseInt(name.slice(2), 16));
36:     }
37:     return whole;
38:   });
39: }
