41: function stripTags(html: string): string {
42:   return html
43:     .replace(/<(script|style)[\s\S]*?<\/\1>/gi, " ")
44:     .replace(/<br\s*\/?>/gi, "\n")
45:     .replace(/<\/(p|div|li|h[1-6])>/gi, "\n")
46:     .replace(/<[^>]+>/g, " ");
