49: export function htmlToText(html: string): string {
50:   // Twice on purpose: feeds routinely ship escaped markup, so one decode leaves
51:   // real tags behind in the text.
52:   return stripTags(decodeEntities(stripTags(html)))
53:     .replace(/[ \t]+/g, " ")
54:     .replace(/[ \t]*\n[ \t]*/g, "\n")
55:     .replace(/\n{3,}/g, "\n\n")
56:     .trim();
57: }
