64: function tag(block: string, names: string[]): string | null {
65:   for (const name of names) {
66:     const match = block.match(
67:       new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`, "i"),
68:     );
69:     if (match) {
70:       const value = unwrap(match[1]!);
71:       if (value) return value;
72:     }
73:   }
74:   return null;
