77: function link(block: string): string | null {
78:   const plain = tag(block, ["link"]);
79:   if (plain?.startsWith("http")) return plain;
80: 
81:   // Atom puts the URL in an attribute, and often lists several rel values.
82:   const alternate = block.match(
83:     /<link[^>]*rel=["']alternate["'][^>]*href=["']([^"']+)["']/i,
84:   );
85:   if (alternate) return decodeEntities(alternate[1]!);
86:   const anyHref = block.match(/<link[^>]*href=["']([^"']+)["']/i);
87:   if (anyHref) return decodeEntities(anyHref[1]!);
88:   const guid = tag(block, ["guid", "id"]);
89:   return guid?.startsWith("http") ? guid : null;
