248:         ? hit.i
249:         : hit.j;
250:     const dropIdx = keepIdx === hit.i ? hit.j : hit.i;
251:     const kept = reattachMarkers(paras[keepIdx]!, paras[dropIdx]!);
252:     const next = paras.filter((_, idx) => idx !== dropIdx);
253:     next[keepIdx < dropIdx ? keepIdx : keepIdx - 1] = kept;
254:     current = next.join("\n\n");
